  "about.founder.p1": "你好，我係康塞普西翁，Luminous StockHaven 嘅創辦人。",
  "about.founder.p2": "我唔係來自大科技公司，亦唔係坐喺企業辦公室。我係一個小零售商，同你一樣。我打理五間電子商務商店，專營書籍同為書迷手工製作嘅配飾。\n同好多獨立零售商一樣，當我試住管理多個地點嘅庫存、將出版商嘅 ISBN 同我自己嘅手工 SKU 一齊跟蹤，同用笨重嘅試算表處理供應商訂單嗰陣，我去到崩潰邊緣。當我搵一個可以幫到我嘅應用程式嗰陣，我試咗六個唔同嘅選擇。每一個都係完全唔完整、令人難以置信咁混亂，或者係掠奪性嘅——為基本工具每月收幾百美元。",
  "about.founder.p3": "對一個榨取獨立創作者嘅行業感到沮喪之後，我決定起自己嘅解決方案。我出於必要而起咗 Luminous StockHaven，為咗乾淨、高效、心安咁打理我自己嘅生意。",
  "about.founder.p4": "我決定以誠實、實惠嘅價錢向公眾開放呢個平台，因為每一個小商家都值得擁有真正好用、又唔危及生計嘅工具。我哋係獨立擁有嘅，我哋堅決守護我哋嘅社區，我哋係由一個零售商為零售商而起嘅。",
