  "auth.sameEmailNotice": "已經喺 Google Play 或者 App Store 用緊我哋嘅應用程式？喺呢度用返同一個電郵 — 即係你登入應用程式用嗰個 — 咁你嘅商店同庫存就會跟住你。用另一個電郵會開一個全新、空嘅店面。",
