  "pos.shopify.connect": "連接 Shopify",
  "pos.shopify.connectedToast": "Shopify 已連接。佢嘅銷售而家會喺呢度計算。",
  "pos.shopify.domainPlaceholder": "your-store.myshopify.com",
  "pos.shopify.help": "Shopify POS 銷售就係 Shopify 訂單。連接此商店後，每筆訂單都會自動從呢度嘅庫存中扣除佢嘅產品。",
  "pos.shopify.tokenNote": "權杖來自你 Shopify 管理後台入面嘅自訂應用程式。佢只儲存在伺服器上，絕唔會再顯示出嚟。",
  "pos.shopify.tokenPlaceholder": "來自你 Shopify 自訂應用程式嘅存取權杖",
