  "pricing.sectionTitle": "銷售定價",
  "pricing.startLabel": "開始",
  "training.lessons.mgr-pricing.step1": "喺 Business 上面，產品表單有一個「銷售定價」部分。清貨係永久減價——設定咗就保持唔變。限時特價係有日期嘅促銷：設定特價、開始日期同結束日期。",
  "training.lessons.mgr-pricing.step2": "你永遠唔使重新輸入正常價錢：佢保留喺產品上面，並顯示喺產品列表同掃描器入面特價嘅隔籬，咁任何人都可以睇到件貨平時幾多錢。",
  "training.lessons.mgr-pricing.step3": "限時特價開始嗰陣打印新嘅價錢標籤——標籤打印嘅係客人嗰日俾嘅價錢。結束日期過咗之後，價錢會自己恢復做正常價錢；當你刷新貨架嗰陣重新打印正常標籤。",
  "training.lessons.mgr-pricing.step4": "如果「銷售定價」部分顯示為鎖定，即係話嗰間企業唔喺 Business 計劃上面——銷售定價屬於嗰個計劃，只有老闆先可以更改計劃。",
  "training.lessons.mgr-pricing.title": "做促銷：清貨同限時特價",
  "training.lessons.owner-pricing.step1": "產品表單入面嘅「銷售定價」之下有兩種減價。清貨係永久嘅：設定清貨價之後，佢會一直平，直到你改返轉頭。限時特價係臨時促銷——一個低啲嘅價錢，有開始日期同結束日期，就好似你喺大舖頭已經熟悉嘅促銷一樣。",
  "training.lessons.owner-pricing.step2": "正常價錢永遠唔會被刪除。限時特價進行期間，應用程式會顯示特價，並喺隔籬顯示正常價錢；打印嘅標籤用特價，咁貨架同收銀處就一致。",
  "training.lessons.owner-pricing.step3": "結束日期過咗之後，價錢會自己返去正常價錢——唔使記住任何嘢，亦唔使撤銷。未開始嘅限時特價會喺產品列表上面直接講明佢幾時開始。",
  "training.lessons.owner-pricing.step4": "銷售定價係 Business 計劃嘅功能。喺 Essentials 上面，呢啲欄位保持鎖定；如果一間企業降到 Essentials 之後再返嚟，佢嘅清貨同限時特價設定仍然原封不動，同當初離開時一模一樣。",
  "training.lessons.owner-pricing.title": "清貨同限時特價定價（Business 計劃）",
