  "print.carrier.desc": "好似今日噉向承運商買郵資 — 呢個應用從來唔賣郵資，所以你俾嘅永遠係承運商自己嘅價錢。將標籤檔案保存喺呢度，佢會永久留喺呢張訂單上面：你嘅記錄，以防萬一，隨時都喺手邊。",
