  "print.style.previewText": "快速的棕色狐狸跳过懒狗。1234567890",
  "training.lessons.owner-shipping-labels.step1": "列印中心喺兩個方案都有「郵寄標籤」樣式：揀一個客戶訂單，就可以列印一張 4×6 標籤，上面有買家姓名同地址，同埋作為寄件人嘅你嘅店舖。",
  "training.lessons.owner-shipping-labels.step2": "呢張標籤同所有客戶單據一樣係白標：上面只有你嘅店舖名稱——永遠唔會出現呢個應用程式嘅名——所以由你店寄出嘅包裹睇落就係嚟自你間店。",
  "training.lessons.owner-shipping-labels.step3": "顧客嘅地址會跟住佢哋嘅訂單保留到最後一次落單之後 90 日；如果訂單存有地址，標籤會由嗰個地址開始；列印嗰陣為一次性標籤輸入嘅地址唔會儲存返去。姓名仍然會由訂單填入，咁標籤就會同單據對得上。",
  "training.lessons.owner-shipping-labels.step4": "呢張標籤透過同所有標籤一樣嘅四種連接列印——藍牙、Wi-Fi、乙太網同 USB——4×6 熱感打印機係佢嘅標準尺寸。",
  "training.lessons.owner-shipping-labels.step5": "改咗向承運商買郵資？喺同一個區域，你可以上傳承運商嘅標籤檔案 — PDF、PNG 或 JPG — 佢會永久保存喺訂單上面：你嘅記錄，以防萬一，隨時都喺手邊。佢會以真實嘅 4×6 尺寸列印。呢個應用從來唔賣郵資，所以承運商嘅價錢係唯一嘅價錢 — 而且永遠係正確嘅價錢。",
  "training.lessons.owner-shipping-labels.title": "客戶訂單郵寄標籤",
  "training.lessons.print-shipping-label.step1": "訂單準備好寄出嗰陣，打開列印中心，揀「郵寄標籤」樣式，再揀客戶訂單。買家姓名會由訂單自動填入。",
  "training.lessons.print-shipping-label.step2": "檢查包裹要寄去嘅地址。當訂單帶有顧客地址嗰陣 — 會保留到最後一次落單之後 90 日 — 佢會自動填入；你列印嗰陣輸入嘅地址唔會儲存返去，所以列印之前請仔細核對郵政編碼同最後一行。",
  "training.lessons.print-shipping-label.step3": "你嘅店舖名稱會作為寄件人列印喺頂部。如果你想連你嘅地址都印埋上標籤，就喺寄件人地址欄輸入；唔想出現就留空。",
  "training.lessons.print-shipping-label.step4": "用 4×6 標籤列印——熱感標籤打印機係常見選擇——或者透過瀏覽器列印掣用任何打印機列印。將標籤平貼喺包裹上面，唔好折到邊。",
  "training.lessons.print-shipping-label.step5": "如果郵資係向承運商買嘅，請改為將佢哋嘅標籤檔案保存喺訂單上面：喺「你嘅承運商標籤」區域上傳承運商俾你嘅 PDF、PNG 或 JPG。佢會作為你嘅記錄留喺訂單上面，並以真實嘅 4×6 尺寸列印 — 而當你想用嗰陣，應用自己嘅地址標籤亦隨時都喺度。",
  "training.lessons.print-shipping-label.title": "列印郵寄標籤",
