  "settings.install.title": "下載應用程式",
  "settings.install.description": "將 Luminous StockHaven 裝到呢部裝置上 — 或者喺佢唔見咗嗰陣將佢搵返。佢直接由本網站安裝（無需應用商店），並由你嘅主畫面全螢幕開啟。",
  "settings.install.button": "下載應用程式",
