  "settings.install.manualIntro": "目前冇可用嘅安裝提示。你仍然可以手動新增應用程式：",
  "settings.install.iosSteps": "喺 Safari 入面，點按共享按鈕，然後點按「加入主畫面」，然後點按「加入」。應用程式會好似任何其他應用程式一樣喺你嘅主畫面上。",
  "settings.install.androidSteps": "喺瀏覽器入面，點按選單（三個點），然後點按「安裝應用程式」或「加入主畫面」，並確認。應用程式會好似任何其他應用程式一樣喺你嘅主畫面上。",
  "settings.install.desktopSteps": "喺瀏覽器嘅網址列入面，如果顯示安裝圖示，請按一下佢。如果冇圖示，請開瀏覽器選單並選擇「安裝 Luminous StockHaven」或「加入桌面」。",
  "staffWelcome.title": "歡迎嚟到 Luminous StockHaven",
