  "staffWelcome.editor.title": "俾新員工嘅歡迎訊息",
  "staffWelcome.editor.description": "新員工喺首次登入嗰陣、喺一切之前只讀一次嘅說話。用你自己嘅說話嚟寫，令佢感覺似你嘅舖。",
  "staffWelcome.editor.permanentNote": "第一行係應用程式本身 — 佢始終顯示，冇辦法更改或刪除。",
  "staffWelcome.editor.tokens": "喺應該出現呢個人名嘅地方寫 {name}，喺應該出現你舖頭名嘅地方寫 {store} — 應用程式會為每個人填好。",
  "staffWelcome.editor.emptyNote": "將個框留空就得用應用程式嘅標準歡迎語（喺框入面淡淡顯示）。新員工永遠唔會見到空白頁面。",
  "staffWelcome.editor.save": "儲存歡迎訊息",
  "staffWelcome.editor.saved": "歡迎訊息已儲存。",
  "training.lessons.staff-shift-windows.title": "你嘅登入跟隨你嘅班次",
  "training.lessons.staff-shift-windows.step1": "你可以由預定班次開始前約 10 分鐘起登入。喺嗰之前，應用程式會保持關閉 — 登入頁面會話你知下一個班次幾時開始。",
  "training.lessons.staff-shift-windows.step2": "一旦你打卡下班，你有 10 分鐘查看你嘅頁面，因為你將被登出，直到你嘅下一個預定日期。",
  "training.lessons.staff-shift-windows.step3": "如果你喺嗰 10 分鐘入面重新打卡上班，登出將被取消，你將保持登入狀態。",
  "training.lessons.staff-shift-windows.step4": "排班表上冇班次意味住嗰日冇辦法登入。如果你認為自己應該喺排班表上，請問你嘅經理或所有者 — 發布打開你大門嘅排班表嘅係佢哋。",
  "training.lessons.manager-shift-windows.title": "發布排班表會開啟同關閉存取權限",
  "training.lessons.manager-shift-windows.step1": "你為團隊發布嘅排班表唔單止係班次列表：佢開啟同關閉每個人嘅應用程式存取權限。團隊成員可以由你為佢發布嘅班次前約 10 分鐘起登入 — 唔可以更早。",
  "training.lessons.manager-shift-windows.step2": "當佢打卡下班嗰陣，佢有大約 10 分鐘查看佢嘅時間，然後應用程式會將佢登出，直到佢嘅下一個預定班次。嗰日冇發布班次意味住佢嗰日冇辦法登入。",
  "training.lessons.manager-shift-windows.step3": "請謹慎發布班次：缺失或錯誤嘅班次會將一個人鎖喺應用程式之外，而唔單止係排班表之外。如果有人話佢入唔到嚟，請先檢查佢嘅排班表。",
  "training.lessons.manager-shift-windows.step4": "你自己嘅存取權限都以同樣嘅方式運作，只係高一個級別：所有者為你發布嘅排班表會喺你嘅班次前約 10 分鐘開啟你嘅視窗，並喺你打卡下班後約 10 分鐘關閉你嘅會話。",
  "training.lessons.owner-shift-windows.title": "班次視窗：排班表開啟同關閉存取權限",
  "training.lessons.owner-shift-windows.step1": "存取權限跟隨你發布嘅排班表。員工或經理可以由佢預定班次前約 10 分鐘起登入 — 唔可以更早。喺班次之外，應用程式對佢哋保持關閉，咁樣舖頭嘅資訊就留喺值班人員手上。",
  "training.lessons.owner-shift-windows.step2": "當佢哋打卡下班嗰陣，佢哋有大約 10 分鐘查看佢哋嘅時間，然後應用程式會自己將佢哋登出，直到佢哋嘅下一個預定班次。喺嗰 10 分鐘入面重新打卡上班會取消登出。",
  "training.lessons.owner-shift-windows.step3": "嗰日冇發布班次意味住嗰日冇視窗：如果某個人唔喺排班表上，佢就冇辦法登入。喺勞動力入面發布排班表，佢嘅大門就會隨之開啟。",
  "training.lessons.owner-shift-windows.step4": "你係唯一嘅例外：冇人為所有者排班，所以你嘅登入永遠冇視窗。經理受你為佢發布嘅排班表所限制，就好似員工受為佢哋發布嘅排班表所限制一樣。",
  "settings.install.ownerNote": "如果你嘅應用商店邊日令你冇辦法用該應用，呢條連結可讓你直接由本網站取得應用 — 無需商店。",
  "layout.signOutLink": "登出",
  "plansLib.includes.teamSettings": "每位團隊成員都有個人設定同登出",
