  "apiErrors.invalidValue.recordingNotPrepared": "嗰段錄音準備唔到 — 請再錄過。",
  "training.lessons.messages-private.step5": "你都可以傳送語音留言：撳訊息框隔籬嘅咪高峰，講嘢，然後撳停止。聽一次先 — 然後傳送，或者刪除咗再錄過。當有人傳俾你嗰陣，撳播放就可以聽到對方真正把聲。",
  "training.lessons.owner-messages-oversight.step5": "已讀標記：當團隊成員睇咗你傳送嘅訊息，你會見到佢標記為已讀。員工同經理用同樣嘅方式互相睇到對方嘅已讀標記，兩個方向都係。",
  "training.lessons.owner-messages-oversight.step6": "你自己嘅閱讀係睇唔到嘅。當你睇員工傳俾你嘅訊息，對方永遠都唔會見到已讀標記 — 而且你唔需要話俾團隊知，佢哋嘅對話會儲存喺應用程式入面，而你作為店主可以睇到。嗰種監督係你照顧你間舖頭嘅一部分。",
  "training.lessons.owner-messages-oversight.step7": "對於員工之間嘅負面訊息，你點樣處理由你決定。可以由佢過去，同某個人靜靜地傾下，或者採取行動 — 選擇權喺你度，你永遠都唔需要講你喺邊度睇到。",
  "staffLib.perm.returnsComplete": "完成退款同換貨",
  "staffLib.area.returnsAccess": "退貨審批",
  "staff.memberDialog.returnsAccessHint": "有呢個剔，呢個人就可以審批退貨，同完成退款或者換貨。冇剔嘅話，佢開始嘅退貨會等店主或者已批准嘅團隊成員處理。",
  "returns.waitingApproval": "等緊店主或者已批准嘅團隊成員審批。",
