  "apiErrors.locationsCreateReserved": "只有老闆，或者老闆允許新增位置嘅團隊成員，先可以新增位置。",
  "settings.policies.title": "你舖頭嘅政策同條款",
  "settings.policies.ownerDescription": "你嘅舖頭,你嘅規則。喺呢度寫低你舖頭嘅政策同條款 — 可以打字輸入,或者上傳一個檔案。每位新團隊成員開始嗰陣會睇到一次,你成隊人隨時都可以喺呢度睇。只有你可以改佢哋。",
  "settings.policies.memberDescription": "你舖頭自己嘅政策同條款,由老闆寫。只有老闆可以改佢哋。",
