  "staffWelcome.policiesIntro": "喺你開始之前:你舖頭嘅政策同條款,由老闆寫。",
  "plansLib.includes.storePolicies": "喺設定入面你自己舖頭嘅政策同條款,畀你成隊人睇",
  "apiErrors.businessPoliciesOwnerOnly": "只有老闆可以改呢間舖頭嘅政策同條款。",
  "apiErrors.policyFileInvalid": "請傳送細過 25 MB 嘅 PDF、文字、Word 或 OpenDocument 檔案。",
  "apiErrors.policyTextTooLong": "嗰份文件太長,冇辦法喺呢度輸入。你可以改為將佢當檔案上傳。",
  "training.lessons.owner-store-policies.title": "你舖頭嘅政策同條款",
  "training.lessons.owner-store-policies.step1": "開啟設定,搵「舖頭政策同條款」卡。入面有兩份文件:你嘅舖頭政策 — 你舖頭嘅屋企規則 — 同埋你嘅條款與細則。",
  "training.lessons.owner-store-policies.step2": "每份文件都可以即場輸入,或者當檔案上傳(PDF、文字、Word 或 OpenDocument,最大 25 MB)。只可以二揀一:儲存文字會更換檔案,上傳檔案會更換文字。移除一份文件會將佢清空。",
  "training.lessons.owner-store-policies.step3": "你嘅團隊會喺佢哋第一次開始嗰陣嘅歡迎頁面睇到呢兩份文件一次,之後隨時都可以喺佢哋嘅設定入面睇。對你嘅團隊嚟講,佢哋係唯讀嘅 — 只有你可以寫或者改佢哋。",
  "training.lessons.owner-store-policies.step4": "每間商戶都保存自己嘅文件:你喺呢度寫嘅嘢只屬於呢間舖頭,永遠唔會出現喺另一間商戶入面。Luminous StockHaven 自己嘅條款同政策喺設定入面你文件嘅隔籬,每個人都可以睇埋佢哋。",
  "training.lessons.welcome-basics.step5": "你舖頭嘅政策同條款會喺你嘅歡迎頁面顯示一次,並保存喺設定入面,你隨時都可以喺嗰度睇。",
  "apiErrors.policyDocNotFound": "嗰份文件唔係兩份入面嘅一份。",
