  "settings.policyQuiz.title": "畀你團隊嘅問題",
  "staff.memberDialog.trainingAccessHint": "閱讀店舖政策同條款係畀所有人嘅。呢啲剔選分配嘅係擁有人喺設定入面每份文件隔籬建立嘅測驗培訓。",
  "staffLib.area.trainingAccess": "政策測驗培訓",
  "staffLib.perm.trainingPoliciesQuiz": "店舖政策測驗培訓",
  "staffLib.perm.trainingTermsQuiz": "條款與條件測驗培訓",
  "training.comment.placeholder": "關於呢堂課嘅任何諗法…",
  "training.comment.send": "傳送留言",
  "training.comment.sent": "你嘅留言已提交畀擁有人。",
  "training.comment.title": "畀擁有人留言",
  "training.lessons.download-app.step1": "Luminous StockHaven 可以好似真正嘅應用程式咁裝喺你部手機或者電腦度 — 唔使應用程式商店。",
  "training.lessons.download-app.step2": "打開設定，搵下載應用程式卡片。每個角色、兩種計劃都有呢張卡片。",
  "training.lessons.download-app.step3": "撳安裝掣，跟住裝置嘅提示做。應用程式會帶住店舖嘅名同圖示出現喺主畫面度。",
  "training.lessons.download-app.step4": "由嗰時開始就喺主畫面打開佢 — 登入方式一樣，顯示嘅都係同一間店舖。",
  "training.lessons.download-app.title": "將應用程式下載到你嘅裝置",
  "training.lessons.mgr-tax-rate.step1": "訂單可以帶一個銷售稅率。稅率本身由擁有人喺設定入面定；成間店舖只有一個稅率。",
  "training.lessons.mgr-tax-rate.step2": "當擁有人喺你嘅員工記錄入面為你剔選稅費部分嗰陣，稅率都會出現喺你嘅設定入面，你可以喺嗰度保持佢最新。",
  "training.lessons.mgr-tax-rate.step3": "稅率係一個百分比 — 8.25 即係顧客喺訂單貨品金額之外仲要畀 8.25% 嘅稅。",
  "training.lessons.mgr-tax-rate.step4": "稅率變嗰陣，新訂單用新稅率。已經落咗嘅訂單保留落單嗰陣嘅稅率。",
  "training.lessons.mgr-tax-rate.step5": "如果店主將稅款轉做自動，新訂單會喺州出現喺訂單上面嗰一刻，用顧客所在州嘅基本稅率填入稅款，州有變動嗰陣仲會重新填入。呢啲係各州嘅基本稅率；地方稅可能會再加。冇州、或者嚟自美國境外嘅訂單，會用商店嘅固定稅率——而喺訂單上面輸入嘅稅款永遠優先。",
  "training.lessons.mgr-tax-rate.title": "店舖嘅稅率",
  "training.lessons.owner-confidentiality.step5": "呢個就係全貌。你嘅團隊睇到嘅係佢哋自己嘅工作 — 佢哋嘅更表、任務、糧單、訊息，同埋佢哋角色開得到嘅店舖頁面。佢哋永遠睇唔到你嘅試用、企業用緊邊個計劃、計劃幾多錢、付款有冇成功，或者有冇去到計劃上限。牽涉到錢嘅頁面 — 賬單、發票、付款方式 — 永遠只有擁有人睇得到。",
  "training.lessons.owner-confidentiality.step6": "如果帳戶畀人停用，你嘅團隊睇到嘅正正係呢條訊息：「更改目前已經關閉。目前冇辦法新增或更改任何內容 — 如果你需要啲乜，請問商家所有者。」 入面冇提到計劃、價錢或者付款。",
  "training.lessons.owner-confidentiality.step7": "而當計劃上限令到某件事畀人攔住嗰陣，顯示嘅正正係呢條訊息：「呢個而家加唔到 — 請問企業擁有人。」 佢永遠唔會講去到上限 — 呢件事只係你同應用程式之間知。",
  "training.lessons.staff-builds.step1": "組合係將產品砌成一件賣得嘅嘢 — 禮包、套裝、禮品套裝。組合喺選單嘅組合頁面入面。",
  "training.lessons.staff-builds.step2": "打開一個組合，睇下佢嘅組成：每個部件產品，同埋組合各用幾多個。",
  "training.lessons.staff-builds.step3": "組合畀人製作或者賣出嗰陣，佢部件嘅庫存會跟住變 — 應用程式會為你保持數量準確。",
  "training.lessons.staff-builds.step4": "如果缺咗某個部件或者數量睇落唔啱，請同你經理講，唔好估 — 組合會同時影響好多產品。",
  "training.lessons.staff-builds.title": "組合同禮包",
  "training.lessons.staff-cross-store.step1": "當你嘅企業有唔止一間店舖或者據點嗰陣，店舖之間可以互相請求庫存。呢啲請求會入到跨店收件箱。",
  "training.lessons.staff-cross-store.step2": "喺選單打開收件箱，睇下另一間店舖請求緊啲乜，同埋你嘅店舖收到啲乜。",
  "training.lessons.staff-cross-store.step3": "只按經理教你嘅方式回覆請求 — 送出庫存會改變你自己店舖嘅數量。",
  "training.lessons.staff-cross-store.step4": "如果請求睇落唔啱 — 件貨錯咗，或者數量多過你有嘅 — 唔好估。請向經理報告。",
  "training.lessons.staff-cross-store.title": "跨店收件箱",
  "training.lessons.staff-reports.step1": "報表將店舖嘅數字 — 銷售、庫存等等 — 匯總埋一齊。報表喺選單入面。",
  "training.lessons.staff-reports.step2": "打開一份報表，睇下佢涵蓋日期嘅數字。日期係報表嘅一部分：同一份報表換一個禮拜，講嘅就係另一個故事。",
  "training.lessons.staff-reports.step3": "有啲報表可以儲存做檔案匯出。只有經理或者擁有人要求嗰陣，先好將報表匯出儲存。",
  "training.lessons.staff-reports.step4": "報表嘅數字嚟自店舖嘅真實工作 — 訂單、盤點同調動 — 所以其他地方都如實輸入，報表先會真實。",
  "training.lessons.staff-reports.title": "睇報表",
  "training.lessons.welcome-basics.step6": "做完之後請登出：每個頁面最底、版權行正上方都有一個登出連結。登出會喺所有裝置上面都登出 — 咁就冇人可以喺共用畫面上面入到你嘅帳戶。",
