  "training.lessons.your-profile-photo.title": "你嘅個人相片",
  "training.lessons.your-profile-photo.step1": "老闆批准之後，你嘅相片會出現喺應用程式頂部你個名隔籬、「員工」頁面上面，同埋你嘅訊息隔籬。喺批准之前，只會顯示你個名嘅縮寫。",
  "training.lessons.your-profile-photo.step2": "打開「設定」，搵「你嘅個人相片」。揀一張你自己嘅相片然後傳送。張相會傳送畀老闆批准——等緊期間唔會出現喺任何地方。",
  "training.lessons.your-profile-photo.step3": "老闆批准之後，你個鈴鐺會響，你嘅相片就會開始顯示。如果未獲批准，揀另一張相片再傳送。",
  "training.lessons.your-profile-photo.step4": "換相片嘅做法一樣：新相片要等批准，新相片獲批之前，你而家張相會保持不變。如果換相未獲批准，你會保留另一張相。",
  "training.lessons.owner-profile-photos.title": "個人相片同你個名",
  "training.lessons.owner-profile-photos.step1": "每個人嘅相片都會顯示喺佢個名隔籬——喺應用程式頂部、你嘅「員工」頁面上面，同埋佢哋嘅訊息隔籬。團隊成員嘅相片喺你批准之前唔會出現喺任何地方——批准權只屬於你，冇人可以批准自己嘅相片。",
  "training.lessons.owner-profile-photos.step2": "有人傳送相片嗰陣，你個鈴鐺會響。打開「員工」頁面睇下，然後揀「批准」或者「唔批准」。如果你唔批准，系統會通知對方揀另一張相片。",
  "training.lessons.owner-profile-photos.step3": "如果有人換相片，新相片同樣要等你批准。等緊期間，佢而家張相會保持不變——如果你唔批准更換，張相亦會繼續保留。",
  "training.lessons.owner-profile-photos.step4": "你自己嘅相片唔使批准：喺「設定」嘅「你嘅個人相片」下面設定。同一張卡仲有你個名——你喺嗰度設定嘅名會喺團隊睇到嘅所有地方取代「老闆」呢個詞，包括應用程式入面同「訊息」入面。",
