  "training.lessons.mgr-clock-callin.title": "臨時叫更同打卡修正",
  "training.lessons.mgr-clock-callin.step1": "老闆可以畀經理兩個分開嘅剔。臨時叫更畀你可以為一名員工開叫更窗口，而打卡板同漏打嘅落班卡畀你可以睇到成隊嘅打卡板，同埋喺員工頁面修正出勤記錄。每個剔都獨立運作 — 經理可以淨係有其中一個。",
  "training.lessons.mgr-clock-callin.step2": "叫更窗口畀一個人喺冇更次覆蓋嗰陣都可以登入同打卡。喺員工頁面，由「叫更同漏打收工卡」卡片開佢。",
  "training.lessons.mgr-clock-callin.step3": "窗口會一直開住，直到嗰個人打咗收工卡 — 之後係平時嘅10分鐘登出寬限 — 或者直到你或者老闆提早閂咗佢。冇嘢會自己閂咗佢。",
  "training.lessons.mgr-clock-callin.step4": "當有人唔記得打收工卡，排更一完，佢嘅記錄就會喺員工頁面同工資單度標記，你同老闆都會收到通知。記錄會一直計時，直到修正為止。",
  "training.lessons.mgr-clock-callin.step5": "喺員工頁面修正記錄：設定返工、收工同休息時間。經理只可以修正員工嘅記錄 — 經理自己嘅記錄由老闆修正。",
  "staffLib.perm.staffDocuments": "員工文件",
  "staffLib.area.documentsAccess": "員工文件",
  "staff.memberDialog.documentsAccessHint": "只限經理 — 剔咗呢項之後，呢位經理可以打開員工成員嘅文件檔案：為每個人保存嘅文書，例如 W-4 表格、求職申請同身份證件副本。系統會先請你確認 — 呢啲檔案含有社會安全號碼同出生日期。呢個剔對普通員工冇任何作用。",
  "staff.documentsWarning.body": "呢個人將會睇到有關你員工成員嘅機密資料，包括社會安全號碼同出生日期。",
