  "staff.documents.mineTitle": "我嘅文件",
  "staff.documents.mineDesc": "你店主為你存喺檔案入面嘅文書 — W-4 表格、你嘅求職申請、稅務表格、身份證件副本。呢個係你自己嘅檔案：入面任何嘢你都可以打開、下載同打印，但呢度冇嘢可以改。",
