  "training.lessons.owner-staff-documents.title": "員工文件",
  "training.lessons.owner-staff-documents.step1": "你團隊入面每個人喺「員工」頁面都有一個文件檔案。上傳你為佢哋保存嘅文書 — W-4 表格、佢哋嘅求職申請、稅務表格、佢哋嘅身份證件副本 — 並為佢哋改個標題，或者保留檔案名稱。",
  "training.lessons.owner-staff-documents.step2": "每次上傳都會保留。加較新嘅版本永遠唔會刪除舊版本 — 所有版本都會留喺清單入面，最新喺前，每個版本都有自己嘅日期同上傳者姓名。",
  "training.lessons.owner-staff-documents.step3": "只有你先睇到員工文件，除非你喺某位經理嘅成員記錄入面授予佢「員工文件」剔。呢個剔預設關閉，任何角色都唔自帶。",
  "training.lessons.owner-staff-documents.step4": "喺剔開啟之前，會有一條警告講明佢嘅含義：呢個人將會睇到有關你員工成員嘅機密資料，包括社會安全號碼同出生日期。文件所屬嗰個人可以打開自己嘅檔案嚟睇、下載同打印 — 但永遠改唔到入面任何嘢。",
  "training.lessons.mgr-staff-documents.title": "員工文件",
  "training.lessons.mgr-staff-documents.step1": "店主已經將「員工文件」剔託付畀你。喺「員工」頁面，你可以打開團隊入面員工成員嘅文件檔案。",
  "training.lessons.mgr-staff-documents.step2": "每個檔案都保留每個版本：當你加較新嘅副本嗰陣，舊副本仍然列喺佢下低，最新喺前，每個版本都有自己嘅日期同上傳者姓名。",
  "training.lessons.mgr-staff-documents.step3": "呢啲檔案可能含有社會安全號碼、出生日期同其他私人資料。只打開你需要嘅嘢，永遠唔好將文件分享到企業之外。",
  "training.lessons.mgr-staff-documents.step4": "店主可以隨時收返個剔，道門會即刻閂埋。經理自己嘅文件只會留喺店主嗰度 — 其他經理都開唔到，不過同所有人一樣，你都可以打開自己嘅檔案嚟睇。",
  "nav.group.restaurant": "餐廳",
  "nav.recipes": "食譜同菜式",
  "nav.restaurant": "餐廳",
  "nav.orderGuide": "訂貨指引",
  "plansLib.businessIncludes.restaurant": "餐廳角落 — 食譜會自動扣減材料，計出菜式真正成本",
  "plansLib.businessIncludes.orderGuide": "補貨點同供應商訂貨指引",
  "staffLib.perm.restaurantBuild": "建立同編輯食譜",
  "staffLib.perm.restaurantPars": "設定補貨點",
  "staffLib.perm.restaurantMoney": "睇菜式成本同利潤",
  "staffLib.area.restaurantAccess": "餐廳使用權",
  "staff.memberDialog.restaurantAccessHint": "餐廳角落人人都可以睇。呢幾個剔號係交出建立食譜、設定補貨點、同睇一碟菜真正成本嘅權限。佢哋只喺 Business 計劃先生效。",
  "training.module.restaurant": "餐廳",
  "training.lessons.owner-restaurant.title": "餐廳角落，店主篇",
  "training.lessons.owner-restaurant.step1": "餐廳角落放住你嘅食譜同菜式。將食譜連結去你賣嘅產品，設定為啟用，之後每賣出一件嗰件產品，佢嘅材料就會自己由貨架扣走 — 經訂單、收銀台同掃描都一樣。",
  "training.lessons.owner-restaurant.step2": "一個食譜可以用另一個食譜做材料 — 例如意粉入面嘅醬汁 — 成本同貨架數量會經兩邊一齊累計。",
  "training.lessons.owner-restaurant.step3": "設定一次製作可以整到幾多，同每種材料嘅出成率 — 即係修剪同煮熟之後，真正可以上枱嘅部分。真正成本係按可以上枱嘅部分計；貨架仍然會扣走你買入嘅全部數量。",
  "training.lessons.owner-restaurant.step4": "Q 因子係用嚟計食譜從來唔會列出嘅細項 — 鹽、油、幾滴檸檬汁。佢只係將嗰個百分比加落菜式成本；絕對唔會由貨架扣走任何嘢。",
  "training.lessons.owner-restaurant.step5": "菜式嘅錢 — 真正成本同食材成本百分比 — 係屬於你嘅，同埋屬於你交咗「睇菜式成本」剔號嘅團隊成員。其他人只會見到菜式、佢嘅價錢同材料，邊度都唔會有成本數字。",
  "training.lessons.staff-restaurant-view.title": "睇菜式同食譜",
  "training.lessons.staff-restaurant-view.step1": "喺 Business 計劃入面，餐廳角落會列出菜式同食譜。打開一個可以睇佢嘅相、用咩材料，同埋一次製作可以整到幾多。",
  "training.lessons.staff-restaurant-view.step2": "當一碟有啟用食譜嘅菜式賣出，佢嘅材料就會自己由貨架扣走。仲係草稿嘅食譜就乜都唔會扣。",
  "training.lessons.staff-restaurant-view.step3": "訂貨指引會話你知要買啲乜：每一種有補貨點嘅材料，佢會計補貨點減去現有數量，再減去已經訂咗嘅數量，然後按供應商嘅包裝數量向上取整。",
  "training.lessons.staff-restaurant-view.step4": "菜式成本係店主先可以分享嘅。如果你見到一碟菜冇成本，嗰個係刻意嘅 — 需要嘅話就問店主。",
  "training.lessons.mgr-restaurant-build.title": "建立食譜",
  "training.lessons.mgr-restaurant-build.step1": "店主已經將「建立食譜」剔號交畀你。喺餐廳角落，你可以逐行加入材料嚟寫食譜 — 每一行都係已經入咗庫存嘅產品，連同一做要用嘅數量。",
  "training.lessons.mgr-restaurant-build.step2": "食譜亦可以由檔案匯入：每行一種材料，寫佢嘅名或者 SKU 同數量。應用程式對唔到嘅行會逐一話你知，絕對唔會靜靜哋刪走。",
  "training.lessons.mgr-restaurant-build.step3": "一個食譜可以用另一個食譜做材料，而食譜會一直保持草稿 — 乜都唔會由貨架扣走 — 直到你將佢設定為啟用，並且連結去你賣嘅產品。",
  "training.lessons.mgr-restaurant-build.step4": "誠實咁設定每種材料嘅出成率：佢係修剪同煮熟之後剩低嘅比例，而菜式嘅真正成本就係按佢嚟計。",
  "training.lessons.mgr-restaurant-pars.title": "設定補貨點同訂貨指引",
  "training.lessons.mgr-restaurant-pars.step1": "店主已經將「補貨點」剔號交畀你。補貨點即係一種材料應該有幾多存貨 — 可以係成間生意，或者其中一個地點。",
  "training.lessons.mgr-restaurant-pars.step2": "將包裝數量設定為供應商賣呢種材料嘅方式 — 一箱十二件，一袋五十件。訂貨指引會將每一個不足嘅數量向上取整到完整包裝。",
  "training.lessons.mgr-restaurant-pars.step3": "指引會計補貨點減去現有數量，再減去已經訂咗嘅數量，按供應商分組，咁一個星期嘅買貨就可以按每個供應商睇成一張短清單。",
  "training.lessons.mgr-restaurant-pars.step4": "送出指引會喺「採購」入面，為嗰個供應商寫一張草稿採購單 — 同其他地方嘅採購單一樣，準備好俾你檢查同送出。",
  "training.lessons.mgr-restaurant-money.title": "睇菜式嘅錢",
  "training.lessons.mgr-restaurant-money.step1": "店主已經將「菜式嘅錢」剔號交畀你。菜式而家會顯示佢哋嘅真正成本 — 材料嘅成本，經入面任何食譜累計 — 喺售價隔離。",
  "training.lessons.mgr-restaurant-money.step2": "食材成本百分比係真正成本除以售價。佢係按每種材料可以上枱嘅部分計，即係計咗出成率之後嘅部分。",
  "training.lessons.mgr-restaurant-money.step3": "如果食譜有 Q 因子，佢已經計咗入真正成本 — 佢係用嚟計食譜唔會列出嘅細項，例如鹽同油。",
  "training.lessons.mgr-restaurant-money.step4": "菜式嘅錢只會留喺生意入面。店主可以隨時收返呢個剔號，啲數字就會即刻由你嘅畫面消失。",
