  "nav.xstoreMessages": "跨店訊息",
  "plansLib.businessIncludes.xstoreMessages": "跨店訊息——你成隊團隊，遍及每一間生意",
  "xstore.title": "跨店訊息",
  "xstore.help": "呢個帳戶上面嘅每一個人，遍及你所有生意，都聚埋喺同一個收件箱入面。你可以喺呢度傳訊息畀佢哋任何人——文字或者語音都得，仲有已送達同已讀嘅標記。你嘅店內訊息會維持原樣。",
  "xstore.empty": "暫時未有任何對話。用「新訊息」開始一段對話啦。",
  "xstore.noPeople": "暫時未有其他人可以傳訊息住。啲人加入咗你其中一間生意同埋登入之後，就會喺呢度出現。",
  "xstore.deliveredLabel": "已送達",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "跨店訊息係商業版計劃嘅一部分。",
  "apiErrors.invalidValue.personNotPartAccount": "嗰個人唔屬於呢個帳戶。",
  "training.lessons.owner-xstore-messages.title": "跨越你啲舖頭嘅訊息，店主篇",
  "training.lessons.owner-xstore-messages.step1": "跨店訊息係第二個收件箱，同店內訊息分開。店內訊息係畀你而家企喺度嗰間舖用嘅；而呢道門可以搵到你帳戶上面嘅每一個人，遍及你擁有嘅每一間生意——最多五間。",
  "training.lessons.owner-xstore-messages.step2": "喺選單打開跨店訊息，就可以同清單上面任何人開始傾偈。清單會顯示你所有生意入面已經登入咗嘅每一位團隊成員，連同佢哋做嘢嗰啲舖頭。",
  "training.lessons.owner-xstore-messages.step3": "啲相都會一齊顯示：每個人都會顯示佢已經批咗嘅頭像相，冇相嘅話就顯示佢個名嘅縮寫。每條訊息都帶住傳送嘅日期同時間。",
  "training.lessons.owner-xstore-messages.step4": "喺你自己傳送嘅訊息下面，訊息送到之後你會見到「已送達」，對方打開段對話之後就會見到「已讀」。語音訊息喺呢度都用得，同店內訊息入面完全一樣。",
  "training.lessons.owner-xstore-messages.step5": "呢度嘅對話只係嗰兩個人之間嘅私人事。你對店內訊息嘅查看權，唔會伸展到其他舖頭嗰邊。",
  "training.lessons.mgr-xstore-messages.title": "跨越你啲舖頭嘅訊息，經理篇",
  "training.lessons.mgr-xstore-messages.step1": "跨店訊息可以搵到呢個帳戶上面嘅每一個人，遍及每一間生意——唔單止係你而家企喺度嗰間舖。佢喺選單入面，同店內訊息分開嘅。",
  "training.lessons.mgr-xstore-messages.step2": "喺清單嗰度開始傾偈：每一位已經登入咗嘅團隊成員都喺嗰度，佢哋做嘢嗰間舖會寫喺佢哋個名隔籬。",
  "training.lessons.mgr-xstore-messages.step3": "傳送文字，或者錄一段語音訊息。語音訊息傳送之前，你可以聽返、掉咗佢或者傳送出去——同店內訊息一樣。",
  "training.lessons.mgr-xstore-messages.step4": "你嘅訊息送到嗰陣會顯示「已送達」，對方打開段對話嗰陣就會顯示「已讀」。每個名隔籬張相，係嗰個人已經批咗嘅頭像相。",
  "training.lessons.staff-xstore-messages.title": "跨越你啲舖頭嘅訊息",
  "training.lessons.staff-xstore-messages.step1": "跨店訊息係你可以搵到呢個帳戶上面任何人嘅地方，唔理佢喺老闆邊一間生意做嘢——想問另一間舖嘢，唔使再等。",
  "training.lessons.staff-xstore-messages.step2": "喺選單打開佢，揀啱個人，然後寫訊息。如果你要搵嗰個人唔喺清單入面，即係佢仲未登入——佢一登入就會即刻出現。",
  "training.lessons.staff-xstore-messages.step3": "你喺呢度都可以傳送語音訊息：錄音、聽返，然後傳送或者掉咗佢。每條訊息都會顯示傳送嘅日期同時間。",
  "training.lessons.staff-xstore-messages.step4": "當你傳送訊息嗰陣，送到之後會顯示「已送達」，對方打開段對話之後就會顯示「已讀」。段對話只係你同對方兩個人之間嘅私人事。",
