  "training.lessons.owner-restaurant-ops.title": "餐廳運作，店主篇",
  "training.lessons.owner-restaurant-ops.step1": "供應商發票喺餐廳角落入面。入返供應商開咗嘅單，連結去佢張採購單，個app就會做三方對數——訂咗、收咗同開咗單，並排嚟睇——仲會標出任何唔夠數、多咗，或者用另一個價開單嘅行。",
  "training.lessons.owner-restaurant-ops.step2": "當發票有一行用同記錄成本唔同嘅價嚟開一件產品嘅單嗰陣，發票頁就會彈出一個價格提示。接受個提示會將產品成本更新做開單價；唔理佢就會keep返成本冇變。",
  "training.lessons.owner-restaurant-ops.step3": "損耗記錄會記低廚房掉咗嘅所有嘢，連埋原因——壞咗、整多咗、備餐出錯、退返嚟、倒瀉咗，或者其他——記錄低佢就會自己將庫存由貨架扣走。到期批次按最快到期先出嚟排，所以最早嗰個到期日會先用，你亦可以為你剔咗嘅批次列印日期標籤。",
  "training.lessons.owner-restaurant-ops.step4": "致敏原表會按每碟菜食譜嘅材料，對住九大主要致敏原嚟計佢嘅致敏原，等客人問嗰陣，係照記錄答，唔係靠記憶。溫度記錄、沽清牌同員工餐係成隊人都用得——唔使剔——因為日常記錄要人人都做到先work。",
  "training.lessons.owner-restaurant-ops.step5": "菜單工程會按每碟菜賣出幾多同賺到幾多嚟擺位：明星、耕馬、謎團同狗仔。差異頁會將食譜話應該由貨架走咗嘅，同員工餐、損耗、同其他所有出咗去嘅嘢嚟比較——剩低嗰啲就係解釋唔到。會計匯出會將收咗貨嘅買貨、損耗、員工餐同食譜扣減，整理做一本簿畀你入數。",
  "training.lessons.staff-restaurant-daily.title": "廚房嘅日常習慣",
  "training.lessons.staff-restaurant-daily.step1": "有嘢掉咗嗰陣，即日喺損耗記錄度記低：係啲乜、幾多、同原因——壞咗、整多咗、備餐出錯、退返嚟、倒瀉咗，或者其他。記錄低佢就會自己將庫存由貨架扣走；你唔使另外再改庫存。",
  "training.lessons.staff-restaurant-daily.step2": "你check每個雪櫃、冰櫃同保溫溫度嗰陣就記低佢。記錄會keep住你個名同時間，仲會標出任何出咗安全範圍嘅讀數——將你做咗啲乜嚟處理寫低做跟進處理。",
  "training.lessons.staff-restaurant-daily.step3": "沽清牌就係而家賣晒啲乜。件嘢一賣晒就即刻貼上牌，等成隊人即刻知道，返貨嗰陣就清走佢——塊牌會keep住邊個清同幾時清。",
  "training.lessons.staff-restaurant-daily.step4": "團隊食嘢嗰陣，記低做員工餐。每一餐都會將佢碟菜由貨架扣走，同用碟菜食譜嘅材料，同賣出一次一樣。員工餐係嗰日真金白銀嘅成本，應該要記錄低。",
  "training.lessons.mgr-restaurant-invoices.title": "發票、批次同run批次",
  "training.lessons.mgr-restaurant-invoices.step1": "店主信得過你，畀咗你「建立食譜」個剔，佢仲會開埋廚房嘅製作工作：供應商發票、到期批次同批量製作。入一張供應商發票，連埋佢啲行——產品、數量同開單成本——有採購單嗰陣就連結埋去。",
  "training.lessons.mgr-restaurant-invoices.step2": "連結咗採購單之後，張發票會逐行做三方對數：訂咗啲乜、收咗啲乜、同開咗單啲乜。一行可以返嚟係啱數、唔夠數、多咗、用另一個價開單，或者根本唔喺張單上面。",
  "training.lessons.mgr-restaurant-invoices.step3": "開單價同產品記錄成本唔同嗰陣，就會彈出價格提示。接受個提示會將產品成本set做新嘅開單價；唔理佢就乜都唔會變。同一張發票同同一件產品，同一時間只會有一個開住嘅提示。",
  "training.lessons.mgr-restaurant-invoices.step4": "將貨當成一個有到期日嘅到期批次嚟收貨，到期頁會keep住啲批次最快到期先出。Run一次批次會將一個食譜整指定次數：佢會用晒食譜嘅材料，同將整好嘅備餐產品放返上貨架——個食譜要先連結去嗰件備餐產品。",
  "training.lessons.mgr-restaurant-invoices.step5": "當供應商針對發票退返錢嗰陣——爛咗嘅箱、唔夠數嘅交貨、改返啱嘅價錢——喺發票頁面針對嗰張發票記錄做貸項通知單。供應商嚟自發票本身，通知單計入發票仲欠嘅金額：發票會顯示佢已應用嘅貸項同應付餘額。貸項永遠唔可以多過佢張發票，作廢通知單會留佢喺記錄入面，同時停止計數。 需要紙質版嗰陣，可以由嗰行打印呢張憑證——打印出嚟嘅單據係你對供應商貸項嘅自有記錄，並非供應商嘅單據。",
  "training.lessons.mgr-restaurant-reports.title": "菜單工程、差異同啲簿",
  "training.lessons.mgr-restaurant-reports.step1": "店主信得過你，畀咗你「菜式錢銀」個剔，佢仲會開埋廚房嘅錢銀報告：菜單工程、差異同會計匯出。呢啲數字會留喺間生意入面，同所有菜式錢銀一樣。",
  "training.lessons.mgr-restaurant-reports.step2": "菜單工程會按每碟菜喺嗰段期間賣出幾多同賺到幾多嚟擺位。明星賣得好又賺得多；耕馬賣得好但賺得少；謎團賺得多但賣得少；狗仔兩樣都唔得。",
  "training.lessons.mgr-restaurant-reports.step3": "差異頁按產品嚟計：食譜話應該由貨架走咗嘅，同員工餐、損耗、同其他所有出咗庫存嘅嘢並排。剩低嗰啲全部都係解釋唔到——而解釋唔到嗰個數字，就係要去解釋返嗰個。",
  "training.lessons.mgr-restaurant-reports.step4": "會計匯出係廚房一本簿：收咗貨嘅買貨、損耗、員工餐同食譜扣減，每一行連埋佢嘅日期、數量同成本，ready好交畀幫你keep簿嗰個人。",
