  "storefronts.ebayDesc": "將你嘅 eBay 店面連接一次。當有商品喺 eBay 賣出嗰陣，佢嘅數量會喺呢度自己減少，銷售會記錄喺你嘅出入庫記錄入面 — 就好似佢被掃碼出庫一樣。銷售只會單向流動：由 eBay 流入應用程式。",
