  "plansLib.includes.recordPrints": "紙本記錄 — 每週更表、工資登記表、工時表、培訓記錄、政策與條款、員工名冊同價格清單，可以打印已填好嘅版本或者空白俾人手填",
  "training.lessons.staff-record-prints.title": "紙上嘅記錄",
  "training.lessons.staff-record-prints.step1": "應用程式入面差唔多每條記錄而家喺文件樣式工作室都有一個紙本分身：每週更表、工資登記表、工時表、培訓記錄、你店舖嘅政策與條款、員工名冊同產品與價格清單 — 喺 Business 計劃仲有供應商目錄同已填好嘅溫度記錄。每一份都用你保存咗嘅文件樣式、你商戶嘅語言打印，日期按你嘅方式寫。",
  "training.lessons.staff-record-prints.step2": "每一份紙都喺佢條記錄所在嘅地方。喺員工頁面，更表分頁會打印你睇得到嘅每個人成個星期嘅安排，考勤分頁會由佢嘅記錄打印工時表。打印只會顯示你喺嗰個畫面已經睇得到嘅嘢 — 打印永遠唔會擴大任何人嘅可見範圍。",
  "training.lessons.staff-record-prints.step3": "喺工資頁面，預覽一個工資期間再打印登記表：每個人、佢嘅工時、總額、扣除同淨額都喺一張紙上面，俾工資檔案用。喺培訓頁面，團隊部分會打印培訓記錄 — 邊個完成咗啲乜，連埋測驗分數同日期。",
  "training.lessons.staff-record-prints.step4": "你店舖嘅政策與條款會由設定打印出嚟，同你寫嘅一模一樣，準備好交俾新員工或者貼喺牆上。員工頁面打印一頁名冊，產品頁面打印價格清單，喺 Business 入面供應商頁面打印目錄，溫度記錄頁面為食品安全檔案打印已填好嘅記錄。",
  "training.lessons.staff-record-prints.step5": "想要一張人手填嘅表？打印中心嘅空白表格而家為呢啲紙每一份都提供空白分身，兩個計劃都有：打印一張，用筆填好，同打印件放埋一齊存檔。",
  "ageCheck.title": "年齡檢查",
  "ageCheck.intro": "掃描駕駛執照或者身份證背面嘅條碼。你只會得到一個答案——綠色剔號或者紅色剔號——而個應用程式唔會保留掃描入面任何嘢：冇名，冇號碼，冇出生日期，冇任何記錄低嘅嘢。",
  "ageCheck.scanPrompt": "將鏡頭對住執照或者卡背面嘅條碼。",
  "ageCheck.categoryLabel": "賣緊啲乜嘢？",
  "ageCheck.category.alcohol": "酒",
  "ageCheck.category.tobacco": "煙草",
  "ageCheck.category.other": "其他有年齡限制嘅貨品",
  "ageCheck.lineNote": "你對{category}嘅界線：{age}歲或以上",
  "ageCheck.pass": "年齡夠喇——可以賣。",
  "ageCheck.fail": "年齡唔夠——唔好做呢單交易。",
  "ageCheck.expired": "呢張卡已經過期——唔通過。",
  "ageCheck.unreadable": "嗰個碼唔係我哋讀得到嘅身份證條碼。試下執照背面嘅條碼。",
  "ageCheck.checkAnother": "再檢查另一個",
  "ageCheck.back": "返去掃描產品",
  "ageCheck.keepsNothing": "呢次掃描入面冇任何嘢會被儲存、傳送或者記錄。答案就係全部，離開呢個畫面就會冇咗。",
  "settings.ageLines.title": "年齡界線",
  "settings.ageLines.description": "顧客每種交易都要達到嘅年齡，掃描頁面嘅年齡檢查就係用呢個。呢啲界線係由你設定嘅——按照你生意所在地嘅法律嚟設定。應用程式由酒21歲、煙草21歲、其他有年齡限制嘅貨品18歲開始。",
  "settings.ageLines.alcohol": "酒——最低年齡",
  "settings.ageLines.tobacco": "煙草——最低年齡",
  "settings.ageLines.other": "其他有年齡限制嘅貨品——最低年齡",
  "plansLib.includes.ageCheck": "用執照掃描做年齡檢查——掃描身份證背面攞到綠色或者紅色剔號，卡入面任何嘢都唔會保留",
  "training.lessons.scanner-age-check.title": "用執照掃描檢查年齡",
  "training.lessons.scanner-age-check.step1": "有啲貨品淨係可以賣畀超過某個年齡嘅顧客。喺掃描頁面，打開年齡檢查，揀賣緊啲乜嘢——酒、煙草，或者其他有年齡限制嘅貨品——然後掃描顧客駕駛執照或者身份證背面嘅條碼。",
  "training.lessons.scanner-age-check.step2": "答案係兩個剔號入面嘅一個。綠色剔號即係顧客年齡夠，可以賣。紅色剔號即係佢未達到嗰個類別嘅界線，或者張卡過咗期——兩種情況都唔應該賣。",
  "training.lessons.scanner-age-check.step3": "應用程式唔會保留掃描入面任何嘢。冇名、執照號碼或者出生日期會喺任何地方被儲存、傳送或者寫低：檢查答完嗰一條問題就消失。冇一份檢查過嘅卡嘅清單可以翻查——呢個係特登設計嘅。",
  "training.lessons.scanner-age-check.step4": "年齡界線係老闆嘅，佢喺設定入面按照生意所在地嘅法律嚟定。佢哋可以因地方而異，亦可以同應用程式嘅起始界線唔同，而檢查永遠跟住你所在生意嘅老闆界線。",
  "training.lessons.scanner-age-check.step5": "如果個碼讀唔到，畫面會講得清清楚楚。抹下個條碼再試，或者要求睇另一張卡。唔係身份證條碼嘅碼永遠唔會攞到綠色剔號。",
