  "plansLib.includes.ownTraining": "加入你自己嘅培訓——為你嘅團隊寫你自己嘅培訓同測驗",
  "training.lessons.owner-own-training.title": "加入你自己嘅培訓",
  "training.lessons.owner-own-training.step1": "喺培訓頁面嘅最尾有「加入你自己嘅培訓」框。打開佢，開始一個新培訓，同畀佢一個標題——你嘅安全規則、你嘅注意事項、你做事嘅方法。",
  "training.lessons.owner-own-training.step2": "喺框入面用你自己嘅說話寫培訓本身，或者改為上載做檔案——PDF、文字、Word 或者 OpenDocument 檔案。打入嘅文字會取代已儲存嘅檔案，而檔案會取代打入嘅文字。",
  "training.lessons.owner-own-training.step3": "喺下面整佢嘅測驗：想要幾多題都得，選擇題同書面回答題自由混合。對於書面題，寫低你預期嘅答案；對於選擇題，標記正確嗰個。",
  "training.lessons.owner-own-training.step4": "設定通過線，同選擇書面答案點樣判定：用你嘅答案鎖匙差唔多逐字核對，或者send畀你嚟標記通過或者退回。然後準確剔選邊啲團隊成員上呢個培訓——得佢哋先見到。",
  "training.lessons.owner-own-training.step5": "你儲存嘅每個培訓都喺框入面獨立企好，有自己嘅問題、通過線同剔選，你可以加入幾多都得。結果會出現喺每個培訓下面嘅框入面；只有當伺服器核查咗一次通過嘅作答，培訓先算完成——或者喺批改模式下，當你標記為通過嗰陣。",
  "apiErrors.ownTrainingOwnerWrites": "呢啲培訓只有老闆先可以寫。",
