  "print.pool.title": "產生條碼",
  "print.pool.intro": "喺商品存在之前就產生條碼。印出嚟，貼喺冇自己條碼嘅貨品上面；第日掃描其中一個嗰陣，應用程式會認出呢個碼，並提議新增嗰件商品。",
  "print.pool.countLabel": "你需要幾多個條碼？",
