  "print.pool.savePdf": "儲存為 PDF",
  "print.pool.failed": "產生唔到嗰啲條碼。請再試過。",
  "scan.pool.title": "你自己印嘅條碼之一",
  "scan.pool.body": "呢個仲未係你舖頭嘅商品——係你預先印好嘅條碼。你想唔想將佢新增為商品？",
  "plansLib.includes.barcodePool": "條碼池——預先印好條碼，然後喺每個商品嘅條碼被掃描嗰陣新增嗰件商品",
  "training.lessons.owner-barcode-pool.title": "喺商品之前列印條碼",
  "training.lessons.owner-barcode-pool.step1": "有啲貨品冇自己嘅條碼——手工製品、你自己嘅書袋、任何你親手整或者組合嘅嘢。喺列印部分，「產生條碼」呢道門會喺商品存在之前就產生編碼。",
  "training.lessons.owner-barcode-pool.step2": "講出你需要嘅數量——冇上限——應用程式就會向你企業嘅條碼池鑄造同樣數量嘅新碼。佢哋只屬於你嘅企業，絕對唔會派發兩次，產生佢哋亦唔會產生商品或者庫存。",
  "training.lessons.owner-barcode-pool.step3": "喺佢哋產生嗰一刻揀：即刻印成標籤，或者儲存為 PDF 第日先印。無論邊種方式，啲碼都喺池入面，印出嚟嘅標籤同碼池完全一致。",
  "training.lessons.owner-barcode-pool.step4": "整每件貨品嗰陣貼一個標籤上去。未用嘅碼只係喺池入面等——唔使急，佢哋亦唔會過期。",
  "training.lessons.owner-barcode-pool.step5": "當貼咗標籤嘅貨品第日被掃描嗰陣，應用程式會認出佢自己印嘅碼，並提議新增嗰件商品，個碼已經填好。新增之後，呢個碼就成為嗰件商品嘅碼，同其他任何碼一樣被掃描。",
