  "training.lessons.staff-checklists.title": "做清單",
  "training.lessons.staff-checklists.step1": "清單係你盤生意運作所靠嘅清單——開鋪、閂鋪、清潔,同埋老闆設定嘅一切。喺「清單」入面搵到佢哋:今日嘅清單喺最上面,準備好剔。",
  "training.lessons.staff-checklists.step2": "當你真正做完一個項目嗰陣先剔佢。每個剔都會記低係邊個做、幾時做,咁下一個人——同埋喺屋企嘅老闆——都睇到咩做完咗、咩仲未做。",
  "training.lessons.staff-checklists.step3": "有啲項目喺剔之前要求證明:做完工作嘅相片、代碼嘅掃描,或者輸入嘅溫度。先加證明,再剔——冇證明,項目唔會被剔。",
  "training.lessons.staff-checklists.step4": "唔小心剔咗啲嘢?取消佢嘅剔——但只可以取消自己嘅。經理或者老闆可以取消任何人嘅,因為剔係帶名嘅記錄。",
  "training.lessons.staff-checklists.step5": "做清單從來唔使許可。整範本同揀分配畀邊個係老闆嘅工作,或者老闆畀咗清單範本剔嘅人嘅工作。",
