  "foodSafety.mock.title": "模擬檢查",
  "foodSafety.mock.subtitle": "在檢查員到來之前，像檢查員一樣走遍廚房。",
  "foodSafety.mock.intro": "開始一次模擬檢查，並在檢查時在清單頁面上勾選每個要點。每個勾選都會記錄誰檢查的、何時檢查的 — 沿途修正你發現的問題，檔案會顯示這些工作。",
  "foodSafety.mock.startButton": "開始今天的模擬檢查",
  "foodSafety.mock.startFailed": "無法開始模擬檢查。",
  "foodSafety.mock.startedNote": "你的模擬檢查在今天的清單中。",
  "foodSafety.mock.openChecklists": "打開清單",
  "foodSafety.mock.item1": "冰箱、冰櫃和保溫都在其安全範圍內，溫度日志已填寫。",
  "foodSafety.mock.item2": "冷卻和復熱檢查已記錄，讀數未達標處有糾正措施。",
  "foodSafety.mock.item3": "消毒液已按正確濃度配製，其檢查已記錄。",
  "foodSafety.mock.item4": "每份食品證書都有效，即將到期的證書正在續期中。",
  "foodSafety.mock.item5": "安全數據表在全隊都能閱讀的貨架上。",
  "foodSafety.mock.item6": "有日期的食品已貼標簽，並按到期順序使用：先到期的先用。",
  "foodSafety.mock.item7": "每道菜的過敏原都在過敏原矩阵中標明。",
  "foodSafety.mock.item8": "廢棄物日志是最新的，丟棄的每樣東西都有原因。",
  "training.lessons.staff-food-safety.title": "維護食品安全檔案",
  "training.lessons.staff-food-safety.step1": "食品安全檔案位於餐廳角落的食品安全貨架上：溫度日志、冷卻、復熱和消毒劑日志、證書、安全數據表和檢查包。",
  "training.lessons.staff-food-safety.step2": "超出範圍的讀數在其備注說明你做了什麼 — 重新冷卻、重新加熱、重新配製消毒劑、丟棄 — 之前不算完成。沒有備注，就不保存：該條目不成立。",
  "training.lessons.staff-food-safety.step3": "像記錄溫度一樣記錄冷卻、復熱和消毒劑檢查：你檢查了什麼、讀數，以及未達標時的糾正措施。",
  "training.lessons.staff-food-safety.step4": "證書在到期前會發出警告。當你的證書發出警告時，告訴業主 — 任何人都可以隨時在貨架上閱讀安全數據表。",
  "training.lessons.staff-food-safety.step5": "在檢查之前 — 或任何時候 — 從食品安全貨架運行模擬檢查，並按檢查員的日期打印檢查就緒包。",
