  "training.lessons.staff-equipment.title": "設備記錄與報告故障",
  "training.lessons.staff-equipment.step1": "你生意入面每部機喺設備入面都有自己嘅頁面：幾時買、保養幾時完、邊個維修，同埋發生過嘅一切。",
  "training.lessons.staff-equipment.step2": "當有嘢壞咗，就喺部機本身上面報告。講出咩壞咗，如果可以，加埋問題相片 — 報告會帶住你嘅名同時間入到部機嘅歷史。",
  "training.lessons.staff-equipment.step3": "只有當店主授予你故障報告剔嗰陣，你先可以報告故障。如果個掣唔喺度，話俾店主或者經理知，佢哋會為你開門。",
  "training.lessons.staff-equipment.step4": "保養任務 — 清潔、除垢、維修 — 都有到期日期。設備頁面顯示邊啲到期、邊啲逾期，令任何事都唔會靜靜雞溜走。",
  "training.lessons.staff-equipment.step5": "維修同佢嘅費用由店主或經理記錄。當針對你嘅報告記錄咗維修之後，故障會喺機器歷史入面顯示為已整好。",
