  "training.lessons.owner-tip-pooling.title": "貼士池同貼士記錄",
  "training.lessons.owner-tip-pooling.step1": "打開餐廳，再打開團隊與地點，再打開貼士池。只有店主可以睇到貼士池設定、份額同記錄。",
  "training.lessons.owner-tip-pooling.step2": "揀貼士池點樣分：按小時、按崗位百分比或者按分數。應用會根據已有嘅排班同打卡小時嚟分。",
  "training.lessons.owner-tip-pooling.step3": "揀期間，輸入貼士池金額，預覽分配，然後保存。保存嘅份額會進入嗰個期間嘅工資預覽。",
  "training.lessons.owner-tip-pooling.step4": "準備好嗰陣發布已保存嘅分配 — 團隊成員嗰陣只可以睇到自己嘅份額，發布之前乜都睇唔到。",
  "training.lessons.owner-tip-pooling.step5": "隨時保存貼士記錄：按人、按期間、所報貼士 — 年記錄會將 8% 嘅計算換算成表格可用嘅合計。應用只保存記錄；唔會提交任何嘢。",
