  "apiErrors.laborOwner": "只有店主先可以設定人工盯守數字。",
  "apiErrors.laborSettings": "請檢查人工盯守數字之後再試一次。",
  "training.lessons.owner-labor-warnings.title": "設定人工警告",
  "training.lessons.owner-labor-warnings.step1": "打開排班表，搵到盯守數字。嗰度嘅每個數字都係由你為自己間舖設定嘅。",
  "training.lessons.owner-labor-warnings.step2": "設定對你嚟講加班由每週幾多小時開始，同埋喺應用程式警告你之前，有人可以接近到幾多。",
  "training.lessons.owner-labor-warnings.step3": "設定一個更次入面幾時應該有休息、休息應該有幾長，同埋你想更次入面最早嘅開始同最遲嘅完結。",
  "training.lessons.owner-labor-warnings.step4": "好似平時噉排呢一週。當小時接近你嘅線嗰陣，警告會出現喺排班表上面——喺佢哋過線之前。",
  "training.lessons.owner-labor-warnings.step5": "隨住團隊打卡出入，同一個盯守亦會掃過已工作嘅小時，包括冇攞到嘅休息。",
  "training.lessons.owner-labor-target.title": "按人工目標排呢一週",
  "training.lessons.owner-labor-target.step1": "喺餐廳角落嘅團隊同場所貨架上面打開人工目標。",
  "training.lessons.owner-labor-target.step2": "以百分比輸入你嘅人工目標，同埋你預計今週嘅銷售額。",
  "training.lessons.owner-labor-target.step3": "喺排班表上面排呢一週。預計人工成本同佢嘅%會根據應用程式入面已經有嘅更次同時薪更新。",
  "training.lessons.owner-labor-target.step4": "當預計人工%超過你嘅目標嗰陣，頁面會用明白嘅說話講出嚟，同埋附上背後嘅工時同成本。",
  "training.lessons.owner-labor-target.step5": "當你想將呢一週印喺紙上面嗰陣，由頁面度印——印出嚟嘅表格同你喺屏幕上面睇到嘅係同一份文件。",
  "nav.cateringEvents": "到會同活動",
