  "training.lessons.owner-catering-events.step1": "喺餐廳角嘅樓面與賓客貨架上面打開到會同活動。",
  "training.lessons.owner-catering-events.step2": "加入活動：佢嘅名稱、日期同時間、賓客人數，同埋主辦人嘅姓名同電話。",
  "training.lessons.owner-catering-events.step3": "由你自己嘅菜入面揀菜單，同為每道菜設定份數。",
  "training.lessons.owner-catering-events.step4": "記低已收嘅訂金；應用程式會由活動總額保留應付餘額。錢只有你睇到。",
  "training.lessons.owner-catering-events.step5": "為廚房同樓面列印活動單 — 員工副本唔顯示錢 — 同埋睇吓備餐，活動嘅食材已經出現喺嗰度。",
