  "training.lessons.owner-reservations.title": "接訂枱同管理候位名單",
  "training.lessons.owner-reservations.step1": "喺餐廳角嘅「餐區與客人」架上面打開「訂枱」。訂枱簿保存每一個訂枱；佢下面嘅候位名單保存今晚直接到店嘅客人。",
  "training.lessons.owner-reservations.step2": "加訂枱嗰陣填寫日期同時間、團體嘅名同人數、電話號碼，同埋用你自己嘅話寫嘅枱或者區域。記低廚房需要知道嘅事——過敏、高腳椅、紀念日。",
  "training.lessons.owner-reservations.step3": "問客人想唔想要提醒，只有喺佢哋講「好」嗰陣先好剔個格。提醒透過電郵傳送，短信設置好之後亦都透過短信。將已收嘅訂金——金額同方式——只係作為記錄寫低。",
  "training.lessons.owner-reservations.step4": "成晚推進訂枱簿：將每個團體標記為已入座、冇到或者已取消。由訂枱簿將今日名單傳送俾團隊，等每個人都由同一頁工作。",
  "training.lessons.owner-reservations.step5": "對於直接到店嘅客人，將團體連同告知嘅等候時間加入候位名單。當佢哋張枱準備好嗰陣，撳「枱已準備好」——為嗰條短信提供號碼，就係客人嘅同意。",
  "apiErrors.smsInvalid": "一條短訊需要一個號碼同一個訊息。",
  "apiErrors.smsFailed": "短訊服務冇接受呢個訊息。",
