  "training.lessons.owner-standing-orders.title": "常訂訂單同供應商價格比較",
  "training.lessons.owner-standing-orders.step1": "喺餐廳角嘅庫存與訂購層架開常訂訂單。你嘅重複訂單喺呢度，佢哋下面就係供應商價格簿。",
  "training.lessons.owner-standing-orders.step2": "將常訂訂單設定一次：改個名，揀佢嘅供應商同係邊一日嘅，並用你平時訂開嘅數量加入常備貨行。",
  "training.lessons.owner-standing-orders.step3": "到咗嗰日，撳「整今個星期嘅草稿」。個應用會喺採購部寫一份草稿採購單，用價格簿入面嗰個供應商嘅最新價錢計價 — 請你檢查、改任何需要改嘅嘢，再由你親自 send。個應用絕對唔會自己 send 訂單。",
  "training.lessons.owner-standing-orders.step4": "訂貨之前先睇價格簿：一種食材，每個供應商嘅最新價錢並排比較，最平嗰個喺最前，連埋日期同個價錢係嚟自發票定訂單。",
  "training.lessons.owner-standing-orders.step5": "供應商發票一到就入，令價格簿保持真實 — 每個新價錢都會加入價格簿，下一份草稿會跟住嚟計價。",
