  "prepSuggest.subtitle": "根據你嘅標準庫存量、預訂情況同已經備好嘅數量畀出嘅建議數量。應用程式會展示佢嘅計算 — 喺你執行批量生產之前，單上面乜都唔會變。",
  "prepSuggest.bookedLine": "已預訂：預訂入面嘅客人 {guests} 位 · 即將舉行嘅活動 {events} 場",
