  "training.lessons.owner-production-order.title": "按生產落單同自動填寫嘅備餐單",
  "training.lessons.owner-production-order.step1": "喺餐廳角嘅庫存與訂貨貨架上面打開按生產落單。生產計劃 — 一次批量生產或者一場餐飲活動 — 喺呢度變成食材訂單。",
  "training.lessons.owner-production-order.step2": "揀計劃：批量生產就揀食譜同份數，或者揀一場你已預訂嘅餐飲活動。撳計算訂單。",
  "training.lessons.owner-production-order.step3": "應用程式會展開食譜，減去已有庫存，其餘向上取到包裝規格，並按供應商分組 — 訂貨指南嘅格式。",
  "training.lessons.owner-production-order.step4": "撳產生草稿訂單，每個供應商一張草稿採購單就會去到採購環節。請自己審核同傳送 — 應用程式絕對唔會自己傳送訂單。",
  "training.lessons.owner-production-order.step5": "喺備餐頁，備餐單會自動填寫：建議份數嚟自你嘅標準庫存量、預訂同活動入面嘅預訂情況，同已經備好嘅數量 — 建議只係展示，喺你執行批量生產之前乜都唔會變。",
