  "training.lessons.owner-bar-counting.title": "盤點酒吧：半樽同桶",
  "training.lessons.owner-bar-counting.step1": "由庫存與訂貨貨架開啟酒吧盤點 — 喺你開啟之前佢保持隱藏，所以冇酒吧嘅商戶永遠睇唔到佢。開關只屬於店主。",
  "training.lessons.owner-bar-counting.step2": "打開酒吧盤點，揀你企緊嘅存放區域。張表列出嗰個區域所存嘅物品，每樽同每桶旁邊都有記錄在冊嘅數量。",
  "training.lessons.owner-bar-counting.step3": "每一行說明係樽定桶，輸入滿嘅數量，然後將滑塊移到開咗嗰樽睇落有幾滿 — 以十分之一為單位，對照佢幅圖判斷。盤點數係滿嘅數量加開樽嘅十分之幾。",
  "training.lessons.owner-bar-counting.step4": "保存酒吧盤點。佢會作為普通盤點會話到達盤點 — 送去覆核並喺嗰度應用，貨架就會設為你盤點嘅數量。",
  "training.lessons.owner-bar-counting.step5": "酒吧盤點搵到嘅差異會匯入理論與實際差異，所以成日短缺嘅樽會喺嗰度顯形。當你想將盤點印喺紙上時，由呢頁列印盤點表。",
