  "training.lessons.owner-locations-rollup.title": "所有門市喺一頁上面",
  "training.lessons.owner-locations-rollup.step1": "打開門市貨架,揀所有門市。貨架本身只有當你擁有兩間或以上企業嗰陣先出現,所以得一間門市嘅店主永遠都唔會見到佢。",
  "training.lessons.owner-locations-rollup.step2": "睇每一間門市嗰行:食材成本 %、庫存價值、今個星期浪費同唔夠貨嘅嘢。突出嗰間就係要首先處理嘅弱點。",
  "training.lessons.owner-locations-rollup.step3": "當你想將比較印喺紙上面嗰陣,列印彙總 — 佢會照螢幕上面嘅樣印出嚟。",
  "training.lessons.owner-locations-rollup.step4": "要複製配方,揀咗佢,剔選佢應該去到嘅門市,然後複製。配料先按 SKU 配對,再按名配對;冇配對嘅會喺結果入面俾人點名,絕對唔會靜靜雞丟低。",
  "training.lessons.owner-locations-rollup.step5": "要複製價格,用同樣嘅門市剔選嚟複製價格同成本。如果配方嘅菜式喺某間門市冇配對,佢就會以草稿形式去到嗰度,等你嚟連結。",
