  "ops.invoices.acceptNote": "接受一張發票會令佢嘅價格成為配料嘅目前成本，而用到呢啲配料嘅每個食譜都會重新計算自己嘅成本——食譜會顯示一條備註，寫明佢所依據嘅發票價格。",
  "training.lessons.owner-recipe-cost-link.title": "食譜成本跟隨發票價格",
  "training.lessons.owner-recipe-cost-link.step1": "同送貨核對嗰陣，將供應商發票以草稿形式輸入。",
  "training.lessons.owner-recipe-cost-link.step2": "當發票冇錯嗰陣，將佢嘅狀態設為已接受。",
  "training.lessons.owner-recipe-cost-link.step3": "接受佢會令每個開票價格成為嗰種配料嘅目前成本。",
  "training.lessons.owner-recipe-cost-link.step4": "用到嗰種配料嘅每個食譜都會即刻根據新價格重新計算成本。",
  "training.lessons.owner-recipe-cost-link.step5": "打開一個食譜，睇吓佢嘅成本更新備註，入面寫明佢所依據嘅發票價格——成本從來唔會靜靜雞改變。",
