  "training.lessons.owner-lot-traceability.title": "批次代碼、召回同供應商可追溯性",
  "training.lessons.owner-lot-traceability.step1": "送貨到達嗰陣，打開庫存與訂購貨架上嘅「批次與召回」並記錄：產品、供應商、數量 — 同每個物品箱子上蓋印嘅批次代碼。",
  "training.lessons.owner-lot-traceability.step2": "喺同一個後門屏幕上，記錄冷藏品嘅送貨溫度，同你拒收嘅任何嘢及原因。書面拒收正係供應商貸記所需嘅證據。",
  "training.lessons.owner-lot-traceability.step3": "對於按重量出售嘅商品，記錄到達嘅實際重量。應用程式據此計算每磅或者每公斤嘅真實成本，使食譜成本保持誠實。",
  "training.lessons.owner-lot-traceability.step4": "如果批次被召回，請將佢下架：批次被鎖定以便無人能使用，下架本身成為記錄，剩餘部分連同原因流入廢棄日誌。",
  "training.lessons.owner-lot-traceability.step5": "使用召回查找器同可追溯性日誌回答批次喺邊、去過邊 — 按供應商或者按批次 — 並為衛生部門或者供應商列印日誌。",
