  "training.lessons.owner-spill-log.title": "倒瀉同打爛日誌",
  "training.lessons.owner-spill-log.step1": "先開咗酒吧盤點：倒瀉同打爛日誌同酒吧家族一齊住喺庫存同訂貨貨架上面，佢道門會出現喺酒吧盤點隔籬。",
  "training.lessons.owner-spill-log.step2": "有嘢倒瀉或者打爛嗰陣，立即記錄：物品、倒瀉或者打爛咗幾多、同係倒瀉定打爛。",
  "training.lessons.owner-spill-log.step3": "一定要寫原因 — 發生咗咩事。冇原因嘅倒瀉會俾人拒絕，因為原因就係記錄本身。",
  "training.lessons.owner-spill-log.step4": "呢條記錄按廢棄日誌嘅方式計為損失：庫存經一筆核銷移動離開，一行有成本嘅記錄跌入廢棄日誌，咁差異同總賬就只會見到佢一次。",
  "training.lessons.owner-spill-log.step5": "倒瀉酒水嘅成本得店主先睇到 — 呢次倒瀉令酒吧使咗幾多。需要紙嗰陣，喺佢個頁面打印日誌。",
